// @ts-nocheck
declare const window: any;
import { Component, AfterViewInit, ViewEncapsulation } from '@angular/core';
import { RouterLink, Router } from '@angular/router';
import { AuthService } from '../../core/auth.service';
import { ClassesService } from '../../core/classes.service';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [RouterLink],
  templateUrl: './dashboard.component.html',
  styleUrl: './dashboard.component.css',
  encapsulation: ViewEncapsulation.None
})
export class DashboardComponent implements AfterViewInit {
  private realUserName: string = '';
  private myBookedClassIds: Set<number> = new Set();
  private selectedScheduleDate: Date = new Date();
  private lastScheduleClasses: any[] = [];
  private pendingBookBtn: HTMLElement | null = null;
  private pendingBookClass: any = null;

  constructor(private auth: AuthService, private router: Router, private classesApi: ClassesService) {}

  // Handles data-action/data-arg clicks (replaces original inline onclick="" attributes,
  // which Angular's template compiler disallows for security reasons)
  __run(event: Event): void {
    const el = event.currentTarget as HTMLElement;
    const action = el.dataset['action'];
    const arg = el.dataset['arg'];
    if (action === 'toggleParentOpen') {
      el.parentElement?.classList.toggle('open');
      return;
    }
    if (action && typeof window[action] === 'function') {
      window[action](arg, el);
    }
  }

  private initialsOf(name: string): string {
    return (name || '').trim().split(/\s+/).slice(0, 2).map(p => p[0]?.toUpperCase() || '').join('') || '?';
  }

  private applyUserToDom(user: any): void {
    if (!user) return;
    const initials = this.initialsOf(user.name);
    this.realUserName = user.name || '';

    const tbName = document.getElementById('tbName');
    if (tbName) tbName.textContent = user.name;

    const profileName = document.getElementById('profileNameText');
    if (profileName) profileName.textContent = user.name;

    const sbFootName = document.getElementById('sbFootName');
    if (sbFootName) sbFootName.textContent = user.name;

    const sbAvatar = document.getElementById('sbAvatar') as HTMLElement;
    if (sbAvatar) {
      if (user.avatar) {
        sbAvatar.style.cssText = `background:url(${user.avatar}) center/cover; color:transparent;`;
      } else {
        sbAvatar.textContent = initials;
      }
    }

    const profileAvatar = document.getElementById('profileAvatarLg') as HTMLElement;
    if (profileAvatar) {
      if (user.avatar) {
        profileAvatar.style.cssText = `background:url(${user.avatar}) center/cover; color:transparent;`;
      } else {
        profileAvatar.textContent = initials;
      }
    }

    const epName = document.getElementById('epName') as HTMLInputElement;
    if (epName) epName.value = user.name || '';
    const epEmail = document.getElementById('epEmail') as HTMLInputElement;
    if (epEmail) epEmail.value = user.email || '';
    const epPhone = document.getElementById('epPhone') as HTMLInputElement;
    if (epPhone) epPhone.value = user.phone || '';

    const epAvatarPreview = document.getElementById('epAvatarPreview') as HTMLElement;
    if (epAvatarPreview) {
      if (user.avatar) {
        epAvatarPreview.style.cssText = `background:url(${user.avatar}) center/cover; color:transparent;`;
      } else {
        epAvatarPreview.textContent = initials;
      }
    }
  }

  private async loadRealUser(): Promise<void> {
    try {
      const user = await this.auth.me();
      this.applyUserToDom(user);
      this.applyMemberSince(user.created_at);
      await this.loadMembershipAndTodaysClasses();
      await this.renderSchedulePills();
      await this.loadPosters();
      await this.loadNotifications();
    } catch (err) {
      console.error('Impossible de charger le profil:', err);
      this.router.navigate(['/login']);
    }
  }

  private applyMemberSince(createdAt: string): void {
    if (!createdAt) return;
    const d = new Date(createdAt);
    const label = d.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
    const mcSub = document.getElementById('mcSub');
    if (mcSub) mcSub.textContent = `Member since ${label} · Auto-renew enabled`;
    const profileTier = document.getElementById('profileTierText');
    if (profileTier) profileTier.textContent = `Member since ${label}`;
  }

  private async loadMembershipAndTodaysClasses(): Promise<void> {
    try {
      const home: any = await this.classesApi.getDashboardHome();
      const m = home?.membership;
      if (m) {
        const tier = document.getElementById('mcTier');
        if (tier) tier.textContent = `${(m.plan_name || 'MEMBERSHIP').toUpperCase()} MEMBERSHIP`;
        const status = document.getElementById('mcStatus');
        if (status) status.textContent = m.status === 'active' ? 'Active' : m.status;
        const used = m.classes_used_this_month ?? 0;
        const total = m.classes_per_month;
        const quota = document.getElementById('mcQuota');
        if (quota) quota.textContent = total === null || total === undefined ? `${used} / Unlimited` : `${used} / ${total}`;
        const fill = document.getElementById('mcProgressFill') as HTMLElement;
        if (fill) fill.style.width = total ? `${Math.min(100, (used / total) * 100)}%` : '100%';
        const renew = document.getElementById('mcRenewDate');
        if (renew && m.renews_at) {
          renew.textContent = new Date(m.renews_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
        }
      }
    } catch (err) {
      console.error('Erreur chargement abonnement:', err);
    }

    await this.loadTodaysClasses();
  }

  private async loadTodaysClasses(): Promise<void> {
    const grid = document.getElementById('hclassGrid');
    if (!grid) return;
    try {
      const start = new Date(); start.setHours(0, 0, 0, 0);
      const end = new Date(); end.setHours(23, 59, 59, 999);
      const [classes, bookings] = await Promise.all([
        this.classesApi.listClasses(start, end),
        this.classesApi.myBookings(),
      ]);
      this.myBookedClassIds = new Set(bookings.filter((b: any) => b.status === 'booked').map((b: any) => b.class_id));

      if (!classes.length) {
        grid.innerHTML = `<div class="hclass-card"><div class="hclass-meta">No classes scheduled today.</div></div>`;
        return;
      }
      grid.innerHTML = classes.slice(0, 3).map((c: any) => {
        const start = new Date(c.starts_at);
        const end = new Date(c.ends_at);
        const timeLabel = `${this.fmtTime(start)} – ${this.fmtTime(end)}`;
        const tagClass = c.spots_left <= 0 ? 'tag-gold' : c.spots_left <= 3 ? 'tag-gold' : 'tag-green';
        const tagText = c.spots_left <= 0 ? 'Full' : c.spots_left <= 3 ? 'Filling fast' : `${c.spots_left} spots left`;
        return `
          <div class="hclass-card">
            <div class="hclass-time">${timeLabel}</div>
            <div class="hclass-name">${c.name}</div>
            <div class="hclass-meta">with ${c.trainer_name} · ${c.location || ''}</div>
            <span class="hclass-tag ${tagClass}">${tagText}</span>
          </div>`;
      }).join('');
    } catch (err) {
      console.error('Erreur chargement cours du jour:', err);
      grid.innerHTML = `<div class="hclass-card"><div class="hclass-meta">Erreur de chargement.</div></div>`;
    }
  }

  private escapeHtml(s: string): string {
    const d = document.createElement('div');
    d.textContent = s ?? '';
    return d.innerHTML;
  }

  private async loadPosters(): Promise<void> {
    const feed = document.getElementById('posterFeed');
    if (!feed) return;
    try {
      const posters = await this.classesApi.listPosters();
      if (!posters.length) {
        feed.innerHTML = `<div class="poster-card"><div class="poster-meta">No announcements yet.</div></div>`;
        return;
      }
      feed.innerHTML = posters.map((p: any) => `
        <div class="poster-card">
          <div class="poster-head">
            <img class="poster-logo" src="assets/logo.svg" alt="EOS">
            <div>
              <div class="poster-user">${this.escapeHtml(p.username)}</div>
              ${p.location ? `<div class="poster-location">${this.escapeHtml(p.location)}</div>` : ''}
            </div>
          </div>
          <div class="poster-text">${this.escapeHtml(p.text)}</div>
          ${p.image_url ? `<img class="poster-image" src="${p.image_url}" alt="">` : ''}
        </div>`).join('');
    } catch (err) {
      console.error('Erreur chargement annonces:', err);
      feed.innerHTML = `<div class="poster-card"><div class="poster-meta">Erreur de chargement.</div></div>`;
    }
  }

  private async loadNotifications(): Promise<void> {
    const feed = document.getElementById('notifFeed');
    if (!feed) return;
    try {
      const items = await this.classesApi.listNotifications();
      if (!items.length) {
        feed.innerHTML = `<div class="notif-row"><div class="notif-text">No notifications.</div></div>`;
        return;
      }
      feed.innerHTML = items.map((n: any) => {
        const thumb = n.image_url ? `<img class="notif-thumb" src="${n.image_url}" alt="">` : `<span class="notif-dot"></span>`;
        const body = `<b>${this.escapeHtml(n.title)}</b>${n.description ? ' — ' + this.escapeHtml(n.description) : ''}`;
        const inner = `${thumb}<div class="notif-text">${body}</div>`;
        return n.link
          ? `<a class="notif-row" href="${n.link}" target="_blank" rel="noopener">${inner}</a>`
          : `<div class="notif-row">${inner}</div>`;
      }).join('');
    } catch (err) {
      console.error('Erreur chargement notifications:', err);
      feed.innerHTML = `<div class="notif-row"><div class="notif-text">Erreur de chargement.</div></div>`;
    }
  }

  private fmtTime(d: Date): string {
    return d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
  }

  private async renderSchedulePills(): Promise<void> {
    const pillsEl = document.getElementById('dayPills');
    if (!pillsEl) return;
    const self = this;
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const monday = new Date(today);
    monday.setDate(today.getDate() - ((today.getDay() + 6) % 7));

    const names = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    pillsEl.innerHTML = names.map((name, i) => {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      const selected = d.toDateString() === today.toDateString() ? ' selected' : '';
      const disabled = d < today ? ' disabled' : '';
      return `<div class="day-pill${selected}${disabled}" data-date="${d.toISOString()}"><div class="dname">${name}</div><div class="dnum">${d.getDate()}</div></div>`;
    }).join('');

    pillsEl.querySelectorAll('.day-pill').forEach((pill: any) => {
      pill.addEventListener('click', () => {
        if (pill.classList.contains('disabled')) return;
        pillsEl.querySelectorAll('.day-pill').forEach((p: any) => p.classList.remove('selected'));
        pill.classList.add('selected');
        self.selectedScheduleDate = new Date(pill.dataset.date);
        self.loadScheduleForSelectedDate();
      });
    });

    await this.loadScheduleForSelectedDate();
  }

  private async loadScheduleForSelectedDate(): Promise<void> {
    const grid = document.getElementById('scheduleClassGrid');
    if (!grid) return;
    grid.innerHTML = `<div class="class-card"><div class="class-info">Loading…</div></div>`;
    try {
      const start = new Date(this.selectedScheduleDate); start.setHours(0, 0, 0, 0);
      const end = new Date(this.selectedScheduleDate); end.setHours(23, 59, 59, 999);
      const [classes, bookings] = await Promise.all([
        this.classesApi.listClasses(start, end),
        this.classesApi.myBookings(),
      ]);
      this.myBookedClassIds = new Set(bookings.filter((b: any) => b.status === 'booked').map((b: any) => b.class_id));
      this.lastScheduleClasses = classes;

      if (!classes.length) {
        grid.innerHTML = `<div class="class-card"><div class="class-info">No classes on this day.</div></div>`;
        return;
      }
      grid.innerHTML = classes.map((c: any) => {
        const start = new Date(c.starts_at);
        const spotsClass = c.spots_left <= 3 ? 'low' : 'ok';
        const spotsText = c.spots_left <= 0 ? 'Full' : `${c.spots_left} spots left`;
        const isBooked = this.myBookedClassIds.has(c.id);
        const levelKey = this.levelKey(c.level);
        const levelBadge = levelKey ? `<span class="level-badge level-${levelKey}">${this.levelLabel(levelKey)}</span>` : '';
        return `
          <div class="class-card">
            <div class="class-time-block"><div class="t1">${this.fmtTime(start)}</div><div class="t2">${start.toLocaleDateString('en-US',{weekday:'short'})}</div></div>
            <div class="class-info">
              <div class="cname">${c.name}${levelBadge}</div>
              <div class="cmeta">${c.trainer_name} · ${c.location || ''}</div>
              <div class="cbottom">
                <span class="cspots ${spotsClass}">${spotsText}</span>
                <button class="book-btn ${isBooked ? 'booked' : ''}" data-class-id="${c.id}" data-booked="${isBooked}" ${c.spots_left <= 0 && !isBooked ? 'disabled' : ''}>
                  ${isBooked ? 'Booked ✓' : 'Book'}
                </button>
              </div>
            </div>
          </div>`;
      }).join('');

      grid.querySelectorAll('.book-btn').forEach((btn: any) => {
        btn.addEventListener('click', () => {
          if (btn.dataset['booked'] === 'true') { this.onBookClick(btn); return; }
          const c = this.lastScheduleClasses.find((x: any) => x.id === Number(btn.dataset['classId']));
          if (c) this.openBookModal(btn, c);
        });
      });
    } catch (err) {
      console.error('Erreur chargement planning:', err);
      grid.innerHTML = `<div class="class-card"><div class="class-info">Erreur de chargement.</div></div>`;
    }
  }

  private levelKey(level: string): string {
    const k = (level || '').toLowerCase();
    if (k.startsWith('deb') || k === 'beginner') return 'debutant';
    if (k.startsWith('inter')) return 'intermediaire';
    if (k.startsWith('exp') || k === 'advanced') return 'expert';
    return '';
  }

  private levelLabel(key: string): string {
    return key === 'debutant' ? 'Débutant' : key === 'intermediaire' ? 'Intermédiaire' : key === 'expert' ? 'Expert' : '';
  }

  private openBookModal(btn: HTMLElement, c: any): void {
    this.pendingBookBtn = btn;
    this.pendingBookClass = c;
    const start = new Date(c.starts_at);
    const nameEl = document.getElementById('bookModalName');
    const metaEl = document.getElementById('bookModalMeta');
    const spotsEl = document.getElementById('bookModalSpots');
    const statusEl = document.getElementById('bookModalStatus');
    const confirmBtn = document.getElementById('bookModalConfirm') as HTMLButtonElement;
    if (nameEl) nameEl.textContent = c.name;
    if (metaEl) metaEl.textContent = `${this.fmtTime(start)} · ${c.trainer_name}${c.location ? ' · ' + c.location : ''}`;
    if (spotsEl) {
      spotsEl.textContent = c.spots_left <= 0 ? 'Full' : `${c.spots_left} spots left`;
      spotsEl.className = 'cspots ' + (c.spots_left <= 3 ? 'low' : 'ok');
    }
    if (statusEl) { statusEl.className = 'book-modal-status'; statusEl.textContent = ''; }
    if (confirmBtn) confirmBtn.removeAttribute('disabled');
    document.getElementById('bookModalBackdrop')?.classList.add('show');
  }

  private closeBookModal(): void {
    document.getElementById('bookModalBackdrop')?.classList.remove('show');
    this.pendingBookBtn = null;
    this.pendingBookClass = null;
  }

  private async confirmBookModal(): Promise<void> {
    if (!this.pendingBookClass) return;
    const classId = this.pendingBookClass.id;
    const statusEl = document.getElementById('bookModalStatus');
    const confirmBtn = document.getElementById('bookModalConfirm') as HTMLButtonElement;
    if (statusEl) { statusEl.className = 'book-modal-status loading'; statusEl.textContent = 'Booking your spot…'; }
    if (confirmBtn) confirmBtn.setAttribute('disabled', 'true');
    try {
      await this.classesApi.book(classId);
      if (statusEl) { statusEl.className = 'book-modal-status success'; statusEl.textContent = 'Spot confirmed ✓'; }
      await this.loadScheduleForSelectedDate();
      await this.loadTodaysClasses();
      await this.loadMembershipAndTodaysClasses();
      setTimeout(() => this.closeBookModal(), 900);
    } catch (err: any) {
      if (statusEl) { statusEl.className = 'book-modal-status error'; statusEl.textContent = err?.error?.error || 'Booking failed. Please try again.'; }
      if (confirmBtn) confirmBtn.removeAttribute('disabled');
    }
  }

  private async onBookClick(btn: HTMLElement): Promise<void> {
    const classId = Number(btn.dataset['classId']);
    const isBooked = btn.dataset['booked'] === 'true';
    btn.setAttribute('disabled', 'true');
    try {
      if (isBooked) {
        await this.classesApi.cancelBooking(classId);
      } else {
        await this.classesApi.book(classId);
      }
      await this.loadScheduleForSelectedDate();
      await this.loadTodaysClasses();
      await this.loadMembershipAndTodaysClasses();
    } catch (err: any) {
      alert(err?.error?.error || 'Erreur lors de la réservation');
      btn.removeAttribute('disabled');
    }
  }

